const renewInstanceCert = `-- name: RenewInstanceCert :exec
UPDATE gateway_instance
SET prev_cert_serial = coalesce(prev_cert_serial, cert_serial), cert_serial = $1, cert_expires_at = $2
WHERE id = $3
`

type RenewInstanceCertParams struct {
	CertSerial    string
	CertExpiresAt time.Time
	ID            uuid.UUID
}

// A set prev_cert_serial means the current serial was never used: the instance
// still holds the previous one, so it stays valid.
func (q *Queries) RenewInstanceCert(ctx context.Context, arg RenewInstanceCertParams) error {
	_, err := q.db.Exec(ctx, renewInstanceCert, arg.CertSerial, arg.CertExpiresAt, arg.ID)
	return err
}

const revokeJoinToken = `-- name: RevokeJoinToken :one
UPDATE gateway_join_token SET revoked_at = coalesce(revoked_at, now())
WHERE id = $1 AND org_id = $2
RETURNING gateway_id, (revoked_at = now())::bool AS revoked_now
`

type RevokeJoinTokenParams struct {
	ID    uuid.UUID
	OrgID uuid.UUID
}

type RevokeJoinTokenRow struct {
	GatewayID  uuid.UUID
	RevokedNow bool
}

// revoked_now: this transaction set revoked_at (an earlier revoke has an earlier time).
func (q *Queries) RevokeJoinToken(ctx context.Context, arg RevokeJoinTokenParams) (RevokeJoinTokenRow, error) {
	row := q.db.QueryRow(ctx, revokeJoinToken, arg.ID, arg.OrgID)
	var i RevokeJoinTokenRow
	err := row.Scan(&i.GatewayID, &i.RevokedNow)
	return i, err
}

const spendJoinToken = `-- name: SpendJoinToken :one
UPDATE gateway_join_token SET uses = uses + 1
WHERE token_hash = $1 AND uses < max_uses AND expires_at > now() AND revoked_at IS NULL
RETURNING id, org_id, gateway_id
`

type SpendJoinTokenRow struct {
	ID        uuid.UUID
	OrgID     uuid.UUID
	GatewayID uuid.UUID
}

func (q *Queries) SpendJoinToken(ctx context.Context, tokenHash []byte) (SpendJoinTokenRow, error) {
	row := q.db.QueryRow(ctx, spendJoinToken, tokenHash)
	var i SpendJoinTokenRow
	err := row.Scan(&i.ID, &i.OrgID, &i.GatewayID)
	return i, err
}

const updateResource = `-- name: UpdateResource :execrows
UPDATE resource
SET name = $1, gateway_id = $2, config = coalesce($3::jsonb, config), updated_at = now()
WHERE id = $4 AND org_id = $5
`

type UpdateResourceParams struct {
	Name      string
	GatewayID *uuid.UUID
	Config    []byte
	ID        uuid.UUID
	OrgID     uuid.UUID
}

func (q *Queries) UpdateResource(ctx context.Context, arg UpdateResourceParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateResource,
		arg.Name,
		arg.GatewayID,
		arg.Config,
		arg.ID,
		arg.OrgID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
